// error.guard.ts
import type { RequestHandler } from '@builder.io/qwik-city';
export const errorGuard: RequestHandler = async ({ redirect, next }) => {
try {
await next();
} catch (error) {
if (error.status === 401) {
throw redirect(302, '/login');
} else if (error.status === 403) {
throw redirect(302, '/forbidden');
// Handle other errors
