import { DatabaseSync } from 'node:sqlite';
import path from 'path';
import fs from 'fs';

const DB_PATH = '/home/user/qwik-app/wiki.db';

// Ensure the parent directory exists
const dbDir = path.dirname(DB_PATH);
if (!fs.existsSync(dbDir)) {
  fs.mkdirSync(dbDir, { recursive: true });
}

let db: DatabaseSync | null = null;

export function getDb(): DatabaseSync {
  if (!db) {
    db = new DatabaseSync(DB_PATH);
    // Initialize schema
    db.exec(`
      CREATE TABLE IF NOT EXISTS revisions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        slug TEXT NOT NULL,
        user TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        content_length INTEGER NOT NULL
      )
    `);
  }
  return db;
}

export interface Revision {
  id: number;
  slug: string;
  user: string;
  timestamp: number;
  content_length: number;
}

export function insertRevision(slug: string, user: string, contentLength: number): void {
  const database = getDb();
  const stmt = database.prepare('INSERT INTO revisions (slug, user, timestamp, content_length) VALUES (?, ?, ?, ?)');
  stmt.run(slug, user, Date.now(), contentLength);
}

export function getRevisions(slug: string): Revision[] {
  const database = getDb();
  const stmt = database.prepare('SELECT id, slug, user, timestamp, content_length FROM revisions WHERE slug = ? ORDER BY timestamp DESC');
  return stmt.all(slug) as Revision[];
}

import { component$ } from '@builder.io/qwik';
import { routeLoader$ } from '@builder.io/qwik-city';
import fs from 'fs';
import path from 'path';
import { marked } from 'marked';

export const useWikiPage = routeLoader$(async (requestEvent) => {
  const slug = requestEvent.params.slug;
  const filePath = path.join('/home/user/qwik-app/wiki-pages', `${slug}.md`);
  try {
    const markdown = await fs.promises.readFile(filePath, 'utf-8');
    const html = await marked.parse(markdown);
    return { html, error: null };
  } catch (err: any) {
    if (err.code === 'ENOENT') {
      requestEvent.status(404);
      return { html: null, error: 'Not Found' };
    }
    requestEvent.status(500);
    return { html: null, error: 'Server Error' };
  }
});

export default component$(() => {
  const page = useWikiPage();
  if (page.value.error === 'Not Found') {
    return (
      <div class="wiki-content">
        <h1>404 - Wiki Page Not Found</h1>
      </div>
    );
  }
  if (page.value.error) {
    return (
      <div class="wiki-content">
        <h1>Error: {page.value.error}</h1>
      </div>
    );
  }
  return (
    <div class="wiki-content" dangerouslySetInnerHTML={page.value.html || ''} />
  );
});

import { type RequestHandler } from '@builder.io/qwik-city';
import fs from 'fs';
import path from 'path';
import { insertRevision } from '../../../lib/db';

export const onPost: RequestHandler = async (requestEvent) => {
  const { params, parseBody, redirect, json, request } = requestEvent;
  const slug = params.slug;

  // Read request body (handles JSON, urlencoded, etc.)
  let body: any = null;
  try {
    body = await parseBody();
  } catch (e) {
    // ignore
  }

  if (!body) {
    try {
      body = await request.json();
    } catch (e) {
      // ignore
    }
  }

  if (!body || typeof body !== 'object') {
    throw json(400, { error: 'Invalid request body' });
  }

  const content = body.content;
  const user = body.user;

  if (typeof content !== 'string' || typeof user !== 'string') {
    throw json(400, { error: 'Missing content or user field' });
  }

  // Save the markdown text to /home/user/qwik-app/wiki-pages/[slug].md
  const wikiPagesDir = '/home/user/qwik-app/wiki-pages';
  if (!fs.existsSync(wikiPagesDir)) {
    fs.mkdirSync(wikiPagesDir, { recursive: true });
  }
  const filePath = path.join(wikiPagesDir, `${slug}.md`);
  await fs.promises.writeFile(filePath, content, 'utf-8');

  // Insert a revision log entry into local SQLite database
  insertRevision(slug, user, content.length);

  // Determine response format based on Content-Type or Accept headers
  const contentType = request.headers.get('content-type') || '';
  const accept = request.headers.get('accept') || '';

  if (contentType.includes('json') || accept.includes('json')) {
    throw json(200, { success: true });
  } else {
    throw redirect(303, `/wiki/${slug}`);
  }
};

